/**
 * Schedules `callback` to run when the browser is idle.
 * Falls back to a `setTimeout` macrotask on environments that don't support
 * `requestIdleCallback` (e.g. Safari < 16.4, SSR).
 *
 * Returns a cancel function that should be called on cleanup to avoid running
 * the callback after the component that scheduled it has unmounted.
 */
export function preloadWhenIdle(callback: () => void): () => void {
  if (typeof requestIdleCallback === 'function') {
    const id = requestIdleCallback(callback)
    return () => cancelIdleCallback(id)
  }

  const id = setTimeout(callback, 0)
  return () => clearTimeout(id)
}
