import type {ItemIdentifier} from '@github-ui/issue-viewer/Types'
import {useCallback, useRef, useState} from 'react'
import {fetchQuery, graphql, useRelayEnvironment} from 'react-relay'

import type {
  useLoadMoreNavItemsQuery,
  useLoadMoreNavItemsQuery$data,
} from './__generated__/useLoadMoreNavItemsQuery.graphql'

// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
const NAV_ITEMS_QUERY = graphql`
  query useLoadMoreNavItemsQuery($query: String!, $first: Int!, $skip: Int) {
    search(query: $query, type: ISSUE_ADVANCED, first: $first, skip: $skip) {
      edges {
        node {
          ... on Issue {
            __typename
            number
            repository {
              name
              owner {
                login
              }
            }
          }
        }
      }
      pageInfo {
        endCursor
        hasNextPage
      }
      issueCount
    }
  }
`

// Module-level skip offset for forward pagination — tracks how many items to skip
let forwardSkipOffset: number | null = null

export function setForwardSkipOffset(offset: number) {
  forwardSkipOffset = offset
}

type LoadMoreState = {
  currentItemCount: number
  totalCount: number
  searchQuery: string
}

// Converts raw GraphQL search results into ItemIdentifier[], filtering to issues only
function extractItems(result: useLoadMoreNavItemsQuery$data): ItemIdentifier[] {
  return (result?.search?.edges ?? []).reduce<ItemIdentifier[]>((acc, edge) => {
    const node = edge?.node
    if (node && node.__typename === 'Issue' && node.repository && node.number != null) {
      acc.push({
        number: node.number,
        owner: node.repository.owner.login,
        repo: node.repository.name,
        type: 'Issue',
      })
    }
    return acc
  }, [])
}

/**
 * Hook for loading additional pages of nav items.
 */
export function useLoadMoreNavItems() {
  const environment = useRelayEnvironment()
  const [isLoading, setIsLoading] = useState(false)
  const loadMoreRef = useRef(false)
  const loadBackRef = useRef(false)

  const loadMore = useCallback(
    async (state: LoadMoreState): Promise<{items: ItemIdentifier[]; hasMore: boolean}> => {
      // Prevent concurrent fetches and bail if we already have all items
      if (loadMoreRef.current || state.currentItemCount >= state.totalCount || forwardSkipOffset === null) {
        return {items: [], hasMore: false}
      }

      loadMoreRef.current = true
      setIsLoading(true)

      try {
        const result = await fetchQuery<useLoadMoreNavItemsQuery>(environment, NAV_ITEMS_QUERY, {
          query: state.searchQuery,
          first: 25,
          skip: forwardSkipOffset,
        }).toPromise()

        const newItems = result ? extractItems(result) : []
        if (newItems.length > 0) {
          forwardSkipOffset = forwardSkipOffset + newItems.length
        }
        const hasMore = result?.search?.pageInfo?.hasNextPage ?? false

        return {items: newItems, hasMore}
      } finally {
        loadMoreRef.current = false
        setIsLoading(false)
      }
    },
    [environment],
  )

  const loadBack = useCallback(
    async (searchQuery: string, backItemCount: number, pageSize: number = 25): Promise<ItemIdentifier[]> => {
      if (loadBackRef.current || backItemCount <= 0) return []
      loadBackRef.current = true
      setIsLoading(true)
      try {
        const skipTo = Math.max(0, backItemCount - pageSize)
        const fetchCount = backItemCount - skipTo

        const result = await fetchQuery<useLoadMoreNavItemsQuery>(environment, NAV_ITEMS_QUERY, {
          query: searchQuery,
          first: fetchCount,
          skip: skipTo || null,
        }).toPromise()

        return result ? extractItems(result) : []
      } catch {
        return []
      } finally {
        loadBackRef.current = false
        setIsLoading(false)
      }
    },
    [environment],
  )

  return {loadMore, loadBack, isLoading}
}
